# First create horizontal palindromes for all rows
grid = [
    [1, 1, 3, 1, 1, 1, 5, 1, 1, 1, 1, 1, 1],
    [3, 3, 1, 3, 1, 1, 5, 1, 1, 1, 1, 1, 1],
    [1, 3, 1, 1, 3, 3, 5, 1, 1, 1, 1, 1, 1],
    [1, 3, 4, 1, 3, 1, 5, 1, 1, 1, 1, 1, 1]
]

horz_pal = []
for row in grid:
    new_row = []
    for pos in range(13):
        val = row[min(pos, 12-pos)]
        new_row.append(val)
    horz_pal.append(new_row)

print("After horizontal palindrome:")
for i, row in enumerate(horz_pal):
    print(f"Row {i}: {' '.join(map(str, row))}")

# Now also make it vertically symmetric by swapping top/bottom pairs
# Row 0↔3, Row 1↔2
vert_sym = [None] * 4
for i in range(4):
    sym_i = 3 - i
    if horz_pal[i] == horz_pal[sym_i]:
        vert_sym[i] = horz_pal[i]
    else:
        vert_sym[i] = horz_pal[sym_i]

print("\nAfter vertical mirror (row i gets row 3-i):")
for i, row in enumerate(vert_sym):
    print(f"Row {i}: {' '.join(map(str, row))}")

